import {SoftwareRenderer} from './software-renderer.js';
import {World,kart} from './world.js';
import * as T from './vendor/three.js';
import {COURSES,DRIVERS,createRace,step,rank,pickup,useItem,loadSave,mod,clamp} from './simulation.js';
import {Sound} from './audio.js';
const $=s=>document.getElementById(s),show=(id,v=true)=>$(id).classList.toggle('hidden',!v);
let save;try{save=loadSave(localStorage.getItem('pocket-rally64-v1'));}catch{save=loadSave(null);}if(matchMedia('(prefers-reduced-motion: reduce)').matches)save.motion=false;
let world,race=null,course=0,driver=0,last=0,accumulator=0,menu=true,modal=null,frameTimes=[],eventCursor=0,bannerTimer=0,toastTimer=0,prevCount=4,renderCounter=0,lastFocus=null,recordWritten=false;
const sound=new Sound();sound.enabled=save.sound;const input={steer:0,drift:false,brake:false,curve:0};const pressed={left:new Set(),right:new Set(),drift:new Set()};
const itemSymbols={boost:'ϟ',shield:'⬡',rocket:'➚',bubble:'◉'},itemNames={boost:'TURBO',shield:'SHIELD',rocket:'ROCKET',bubble:'BUBBLE'};
const format=t=>`${Math.floor(t/60)}:${(t%60).toFixed(2).padStart(5,'0')}`;
function persist(){try{localStorage.setItem('pocket-rally64-v1',JSON.stringify(save));return true;}catch{toast('Device storage is unavailable. Records cannot be saved.');return false;}}
function toast(text){$('toast').textContent=text;$('toast').style.opacity=1;toastTimer=4;}
function banner(text){$('race-banner').textContent=text;$('race-banner').style.opacity=1;bannerTimer=2;}
function clearInput(){for(const s of Object.values(pressed))s.clear();input.steer=0;input.drift=false;input.brake=false;for(const id of ['left','right','drift'])$(id).classList.remove('pressed');}
function syncInput(){input.steer=(pressed.right.size?1:0)-(pressed.left.size?1:0);input.drift=!!pressed.drift.size;for(const id of ['left','right','drift'])$(id).classList.toggle('pressed',pressed[id].size>0);}
function openModal(id){lastFocus=document.activeElement;modal=id;$('menu').inert=true;$('hud').inert=true;show('modal-shade');for(const child of $('modal-shade').children)child.classList.toggle('hidden',child.id!==id);setTimeout(()=>$(id).querySelector('button,input,select')?.focus(),0);}
function closeModal(){show('modal-shade',false);$('menu').inert=false;$('hud').inert=false;modal=null;lastFocus?.focus();}
function pause(){if(!race||!['racing','countdown'].includes(race.phase))return;race.beforePause=race.phase;race.phase='paused';clearInput();sound.suspend();openModal('paused');}
function resume(){if(!race)return;race.phase=race.beforePause||'racing';closeModal();last=performance.now();accumulator=0;sound.start();}
function toMenu(){menu=true;race=null;closeModal();show('hud',false);show('menu');world.camReady=false;clearInput();}
function start(){menu=false;closeModal();show('menu',false);show('hud');race=createRace({length:COURSES[course].length,difficulty:save.difficulty,assist:save.assist,driver,seed:Date.now()>>>0});world.makeRacers(driver);world.camReady=false;world.pickups.forEach(x=>x.cooldown=0);clearInput();last=performance.now();accumulator=0;prevCount=4;recordWritten=false;show('first-tip');$('race-banner').style.opacity=0;sound.start();}
function selectCourse(i){course=mod(i,3);world.build(course);world.makeRacers(driver);$('course-name').textContent=COURSES[course].name;$('course-tag').textContent=COURSES[course].tag;$('course-label').textContent=COURSES[course].label;$('scene-number').textContent=`0${course+1} / 03`;$('course-dots').innerHTML=COURSES.map((_,i)=>`<i class="${i===course?'active':''}"></i>`).join('');}
function selectDriver(i){driver=i;world.makeRacers(driver);$('driver-caption').textContent=DRIVERS[driver].caption;[...$('drivers').children].forEach((b,j)=>{b.classList.toggle('selected',j===i);b.setAttribute('aria-pressed',j===i);});}
function settings(){for(const [id,key]of [['sound-toggle','sound'],['assist-toggle','assist'],['motion-toggle','motion']])$(id).checked=save[key];$('difficulty').value=save.difficulty;openModal('settings');}
function applySettings(){save.sound=$('sound-toggle').checked;save.assist=$('assist-toggle').checked;save.motion=$('motion-toggle').checked;save.difficulty=$('difficulty').value;document.body.classList.toggle('reduced',!save.motion);sound.mute(!save.sound);persist();closeModal();}
function finish(){if(recordWritten)return;recordWritten=true;clearInput();const ranking=rank(race),place=ranking.findIndex(x=>x.id===0)+1;const time=race.racers[0].finishTime;const key=`${COURSES[course].id}-${save.difficulty}-${save.assist?'assist':'manual'}`,old=save.records[key];let isBest=!old||time<old;if(isBest){save.records[key]=time;isBest=persist();}$('medal').textContent=place;$('result-title').textContent=place===1?'A little legend.':place<=3?'Podium, baby!':'What a ride.';$('finish-label').textContent=place===1?'WINNER OF THE LITTLE GRAND PRIX':'FINISH LINE FEELING';$('result-summary').textContent=`${COURSES[course].name} · ${format(time)}`;$('record').textContent=isBest?'NEW PERSONAL BEST ✦':`PERSONAL BEST ${format(save.records[key]||time)}`;
 $('result-list').innerHTML=ranking.map((p,i)=>`<div class="result-row ${p.id===0?'you':''}"><span>${i+1}. ${DRIVERS[p.driver].name}${p.id===0?' · YOU':` #${p.id}`}</span><span>${p.done?format(p.finishTime):`+${Math.round((race.length*3-p.distance)/Math.max(p.speed,1))}s est.`}</span></div>`).join('');sound.fx('finish');if(save.motion){const f=world.frameAt(race.racers[0].distance);world.burst(f.p,0xffc750,70);}openModal('results');}
function fire(){if(useItem(race)){sound.fx('item');banner(itemNames[race.events.at(-1)?.item]||'GO!');}}
function bindInputs(){for(const id of ['left','right','drift']){const b=$(id);b.addEventListener('pointerdown',e=>{if(!race||race.phase!=='racing')return;e.preventDefault();b.setPointerCapture(e.pointerId);pressed[id].add(e.pointerId);syncInput();});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{pressed[id].delete(e.pointerId);syncInput();});}
 $('item').onclick=()=>{if(race)fire();};document.addEventListener('keydown',e=>{if(modal){if(e.key==='Escape'){e.preventDefault();if(modal==='paused')resume();else if(modal==='settings')applySettings();else if(modal==='help')closeModal();}if(e.key==='Tab'){const nodes=[...$(modal).querySelectorAll('button,input,select')].filter(n=>!n.disabled);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}return;}
 if(!race)return;const map={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',' ':'drift'};if(map[e.key]){e.preventDefault();pressed[map[e.key]].add('key');syncInput();}if(e.key==='Escape'){pause();e.preventDefault();}if(e.key.toLowerCase()==='e'&&!e.repeat)fire();});document.addEventListener('keyup',e=>{const map={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',' ':'drift'};if(map[e.key]){pressed[map[e.key]].delete('key');syncInput();}});
 addEventListener('blur',()=>{clearInput();pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){pause();sound.suspend();}else{last=performance.now();accumulator=0;}});addEventListener('resize',()=>world.resize());}
function portraits(){const r=world.software?new SoftwareRenderer(document.createElement('canvas'),true):new T.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true});r.setSize(150,130);r.setPixelRatio(1);r.outputColorSpace=T.SRGBColorSpace;const s=new T.Scene();s.add(new T.HemisphereLight(0xffffff,0x779999,3));const light=new T.DirectionalLight(0xffead0,3);light.position.set(-3,8,5);s.add(light);const c=new T.PerspectiveCamera(37,150/130,.1,50);c.position.set(4,3.8,7);c.lookAt(0,1.7,0);DRIVERS.forEach((d,i)=>{const k=kart(i);s.add(k);r.render(s,c);const b=document.createElement('button');b.className='driver-card';b.setAttribute('aria-label',`Choose ${d.name}, ${d.kind}`);b.innerHTML=`<img alt="" src="${r.domElement.toDataURL()}"><span>${d.name}</span>`;b.onclick=()=>{selectDriver(i);sound.start();sound.fx('click');};$('drivers').append(b);s.remove(k);});r.dispose();}
function frame(now){requestAnimationFrame(frame);if(document.hidden){last=now;return;}const actualDelta=last?(now-last)/1000:1/60;const delta=Math.min(actualDelta,.1);last=now;frameTimes.push(actualDelta*1000);if(frameTimes.length>600)frameTimes.shift();if(toastTimer>0){toastTimer-=delta;if(toastTimer<=0)$('toast').style.opacity=0;}if(bannerTimer>0){bannerTimer-=delta;if(bannerTimer<=0)$('race-banner').style.opacity=0;}
 if(race&&race.phase!=='paused'&&race.phase!=='finished'){
 accumulator+=delta;let steps=0;while(accumulator>=1/60&&steps<5){const p=race.racers[0],f=world.frameAt(p.distance),f2=world.frameAt(p.distance+2);input.curve=(f.t.x*f2.t.z-f.t.z*f2.t.x)/2;step(race,input,1/60);accumulator-=1/60;steps++;}
 if(steps===5)accumulator=0;
 const p=race.racers[0];if(race.phase==='racing'){
 for(const x of world.pickups){if(x.cooldown<=0&&Math.abs(mod(p.distance-x.s+race.length/2,race.length)-race.length/2)<3&&Math.abs(p.lane-x.lane)<2.1&&pickup(race)){x.cooldown=4;world.burst(x.g.position,0x9affdf,12);}}
 for(const x of world.boostPads){if(Math.abs(mod(p.distance-x.s+race.length/2,race.length)-race.length/2)<4&&Math.abs(p.lane-x.lane)<2.6)p.boost=Math.max(p.boost,.7);}
 }
 while(race.events.length){const e=race.events.shift();if(e.type==='go'){sound.fx('go');banner('LET’S GO!');}if(e.type==='pickup'){sound.fx('pickup');banner(itemNames[e.item]+' READY');}if(e.type==='drift'){sound.fx('drift');banner(e.tier===2?'SUPER TURBO!':'DRIFT BOOST!');}if(e.type==='lap'){sound.fx('go');banner(e.lap===3?'FINAL LAP!':`LAP ${e.lap}`);}if(e.type==='hit'&&e.id===0){sound.fx('hit');banner('BUMP! KEEP GOING');}if(e.type==='block'&&e.id===0)banner('SHIELD SAVE!');}
 const count=Math.ceil(race.countdown);$('countdown').textContent=race.phase==='countdown'?Math.min(3,count):'';if(race.phase==='countdown'&&count!==prevCount){prevCount=count;sound.tone(count===1?660:440,.14,'triangle',.5);}
 const place=rank(race).findIndex(x=>x.id===0)+1;$('position').textContent=place;$('ordinal').textContent=['ST','ND','RD','TH','TH','TH'][place-1];$('lap').textContent=p.lap;$('race-time').textContent=format(race.time);$('speed').textContent=Math.round(p.speed*2);$('charge').style.width=`${p.charge/2.4*100}%`;$('charge').style.background=p.charge>1.5?'#ffd364':'#75e9fa';$('drift-label').textContent=p.charge>.65?'RELEASE FOR TURBO':p.boost>0?'TURBO!':'HOLD DRIFT + TURN';$('item').disabled=!race.item;$('item-icon').textContent=itemSymbols[race.item]||'◇';$('item-label').textContent=itemNames[race.item]||'ITEM';$('item').setAttribute('aria-label',race.item?`Use ${itemNames[race.item]}`:'No item collected');if(race.time>8)show('first-tip',false);if(race.phase==='finished')finish();
 }
 if(++renderCounter%60===0)$('world').dataset.diagnostics=JSON.stringify(window.__rally?.snapshot());
 if(race&&renderCounter%4===0)world.drawMap($('minimap').getContext('2d'),race);
 world.update(race,race?.phase==='paused'?0:delta,{menu,motion:save.motion});sound.tick(delta,!menu&&race?.phase==='racing');
}
async function boot(){try{world=new World($('world'));portraits();selectDriver(0);selectCourse(0);bindInputs();$('race-start').onclick=start;$('prev-course').onclick=()=>selectCourse(course-1);$('next-course').onclick=()=>selectCourse(course+1);$('settings-open').onclick=settings;$('settings-close').onclick=applySettings;$('help-open').onclick=()=>openModal('help');$('help-close').onclick=closeModal;$('pause').onclick=pause;$('resume').onclick=resume;$('restart').onclick=start;$('quit').onclick=toMenu;$('garage').onclick=toMenu;$('again').onclick=start;$('next-track').onclick=()=>{selectCourse(course+1);start();};document.body.classList.toggle('reduced',!save.motion);show('loading',false);show('menu');requestAnimationFrame(frame);$('world').addEventListener('webglcontextlost',e=>{e.preventDefault();pause();toast('Graphics paused. Reload to restore the race.');});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline play is unavailable in this browser.'));
 // Read-only diagnostics for QA; no gameplay mutation hooks.
 window.__rally={snapshot:()=>({course:COURSES[course].id,menu,phase:race?.phase,time:race?.time,distance:race?.racers[0].distance,lane:race?.racers[0].lane,charge:race?.racers[0].charge,item:race?.item,position:race?rank(race).findIndex(p=>p.id===0)+1:null,save:{...save},graphics:{...world.stats(),renderer:world.software?'software':'webgl'},frameMs:{mean:frameTimes.reduce((a,b)=>a+b,0)/frameTimes.length,p95:[...frameTimes].sort((a,b)=>a-b)[Math.floor(frameTimes.length*.95)]}})};
 }catch(e){console.error(e);show('loading',false);show('fatal');$('fatal-text').textContent='The 3D engine could not start. Try an up-to-date Safari browser and reload.';}}
boot();
